#pragma once

#include <string>
#include <vector>

namespace app {

struct User {
  std::string name;
  int age;
  std::vector<std::string> tags;
};

}  // namespace app

#pragma once

#include <nlohmann/json.hpp>

#include "model/user.h"

inline nlohmann::json user_to_json(const app::User& u) {
  return {{"name", u.name}, {"age", u.age}, {"tags", u.tags}};
}

inline app::User user_from_json(const nlohmann::json& j) {
  app::User u;
  u.name = j.at("name").get<std::string>();
  u.age = j.at("age").get<int>();
  u.tags = j.at("tags").get<std::vector<std::string>>();
  return u;
}

#include <vector>

#include "model/user_json.h"

std::vector<app::User> parse_users(const nlohmann::json& j) {
  std::vector<app::User> users;
  for (const auto& item : j.at("users")) {
    users.push_back(user_from_json(item));
  }
  return users;
}

nlohmann::json dump_users(const std::vector<app::User>& users) {
  nlohmann::json arr = nlohmann::json::array();
  for (const auto& u : users) {
    arr.push_back(user_to_json(u));
  }
  return {{"users", arr}};
}

